"""Bounded character-prefix-aware DataFrame reordering."""

import heapq
from typing import List, Tuple

import numpy as np
import pandas as pd

from solver import Algorithm


class Evolved(Algorithm):
    """Choose constrained global and row-specific column orders by exact Trie reuse."""

    def __init__(self, df: pd.DataFrame = None):
        """Store the optional frame and the most recently returned row orders."""
        self.df = df
        self._last_orders = None

    @staticmethod
    def _cell_string(value) -> str:
        """Serialize one scalar, replacing scalar missing values with an empty string."""
        missing = pd.isna(value)
        if isinstance(missing, (bool, np.bool_)) and bool(missing):
            return ""
        return str(value)

    @staticmethod
    def _lcp(left: str, right: str) -> int:
        """Return the exact common-prefix length using binary-search slicing."""
        if left == right:
            return len(left)
        low, high = 0, min(len(left), len(right))
        while low < high:
            middle = (low + high + 1) // 2
            if left[:middle] == right[:middle]:
                low = middle
            else:
                high = middle - 1
        return low

    @classmethod
    def _trie_score(cls, strings: List[str]) -> int:
        """Compute ideal character-Trie reuse as sorted adjacent LCP lengths."""
        if len(strings) < 2:
            return 0
        ordered = sorted(strings)
        total = 0
        previous = ordered[0]
        for current in ordered[1:]:
            total += len(current) if current == previous else cls._lcp(
                previous, current
            )
            previous = current
        return total

    @staticmethod
    def _column_positions(columns):
        """Map stringified labels to their unique source positions."""
        positions = {}
        for index, label in enumerate(columns):
            positions.setdefault(str(label), []).append(index)
        return positions

    @classmethod
    def _edges(cls, columns, dependencies, merges):
        """Convert dependency and merge requests into directed index edges."""
        positions = cls._column_positions(columns)
        result = []
        seen = set()

        def add(left, right):
            """Add a non-self, nonduplicate precedence edge."""
            edge = (left, right)
            if left != right and edge not in seen:
                seen.add(edge)
                result.append(edge)

        for pair in dependencies or []:
            if len(pair) != 2:
                continue
            left = positions.get(str(pair[0]), [])
            right = positions.get(str(pair[1]), [])
            if len(left) == 1 and len(right) == 1:
                add(left[0], right[0])

        for block in merges or []:
            if not block:
                continue
            resolved = []
            for label in block:
                found = positions.get(str(label), [])
                if len(found) != 1:
                    resolved = []
                    break
                resolved.append(found[0])
            for left, right in zip(resolved, resolved[1:]):
                add(left, right)
        return result

    @classmethod
    def _constrained_order(cls, width, preference, columns, dependencies, merges):
        """Topologically repair a preferred order while preserving requested edges."""
        outgoing = [[] for _ in range(width)]
        indegree = [0] * width
        for left, right in cls._edges(columns, dependencies, merges):
            outgoing[left].append(right)
            indegree[right] += 1

        rank = {column: position for position, column in enumerate(preference)}
        heap = [
            (rank.get(column, width + column), column)
            for column in range(width)
            if indegree[column] == 0
        ]
        heapq.heapify(heap)

        answer = []
        while heap:
            _, column = heapq.heappop(heap)
            answer.append(column)
            for successor in outgoing[column]:
                indegree[successor] -= 1
                if indegree[successor] == 0:
                    heapq.heappush(
                        heap, (rank.get(successor, width + successor), successor)
                    )

        return answer if len(answer) == width else list(preference)

    @staticmethod
    def _statistics(text):
        """Compute length-weighted repeated-value statistics for every column."""
        rows, width = text.shape
        statistics = []
        for column in range(width):
            counts = {}
            for row in range(rows):
                value = text[row, column]
                counts[value] = counts.get(value, 0) + 1
            pair_mass = 0
            repeat_mass = 0
            total_mass = 0
            for value, count in counts.items():
                length = len(value)
                pair_mass += length * count * (count - 1)
                repeat_mass += length * max(0, count - 1)
                total_mass += length * count
            statistics.append((pair_mass, repeat_mass, total_mass))
        return statistics

    @classmethod
    def _lexical_frontier_orders(cls, text, columns, dependencies, merges):
        """Build one row-specific order by repeatedly choosing the smallest legal cell."""
        rows, width = text.shape
        outgoing = [[] for _ in range(width)]
        predecessors = [[] for _ in range(width)]
        for left, right in cls._edges(columns, dependencies, merges):
            outgoing[left].append(right)
            predecessors[right].append(left)

        orders = []
        for row in range(rows):
            indegree = [len(predecessors[column]) for column in range(width)]
            frontier = [
                (text[row, column], column)
                for column in range(width)
                if indegree[column] == 0
            ]
            heapq.heapify(frontier)

            order = []
            while frontier:
                _, column = heapq.heappop(frontier)
                order.append(column)
                for successor in outgoing[column]:
                    indegree[successor] -= 1
                    if indegree[successor] == 0:
                        heapq.heappush(
                            frontier, (text[row, successor], successor)
                        )

            orders.append(order if len(order) == width else list(range(width)))
        return orders

    @staticmethod
    def _serialize(text, orders):
        """Serialize each source row according to its row-specific column order."""
        return [
            "".join(text[row, column] for column in orders[row])
            for row in range(text.shape[0])
        ]

    @staticmethod
    def _materialize(df, source, orders, serialized):
        """Sort rows by serialized keys and copy original cells without modification."""
        row_order = sorted(
            range(source.shape[0]),
            key=lambda row: (serialized[row], row),
        )
        values = np.empty(source.shape, dtype=object)
        public_orders = []

        for output_row, source_row in enumerate(row_order):
            order = orders[source_row]
            values[output_row, :] = [
                source[source_row, column] for column in order
            ]
            public_orders.append([df.columns[column] for column in order])

        result = pd.DataFrame(
            values,
            index=df.index.take(row_order),
            columns=list(df.columns),
        )
        return result, public_orders

